 if(!cgParsedDate(row.due))return {type:'missingDue',priority:'medium',action:'nudgeDueMissing',evidence:[cgT('dueDate')+': '+cgWT('unknown'),cgT('outstandingLabel')+': '+money(row.currency,open)]};
